def transform(grid):
    out=[r[:] for r in grid]
    R,C=len(grid),len(grid[0])
    pts={(r,c) for r in range(R) for c in range(C) if grid[r][c]==2}
    boxes=[]
    while pts:
        stack=[pts.pop()]; comp=[]
        while stack:
            p=stack.pop(); comp.append(p)
            for d in [(1,0),(-1,0),(0,1),(0,-1)]:
                q=(p[0]+d[0],p[1]+d[1])
                if q in pts: pts.remove(q); stack.append(q)
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        boxes.append((min(rs),min(cs),max(cs)))
    boxes.sort()
    initial_cols=[c for c in range(C) if grid[0][c]==6]
    def hline(r,a,b):
        for c in range(max(0,a),min(C-1,b)+1):
            if 0<=r<R and out[r][c]==7: out[r][c]=6
    def vline(c,a,b):
        if 0<=c<C:
            for r in range(max(0,a),min(R-1,b)+1):
                if out[r][c]==7: out[r][c]=6
    if boxes:
        for c in initial_cols: vline(c,0,boxes[0][0]-1)
    for i,(r,l,rr) in enumerate(boxes):
        top=r-1; bottom=(boxes[i+1][0]-1 if i+1<len(boxes) else R-1)
        hline(top,l-1,rr+1)
        vline(l-1,top,bottom); vline(rr+1,top,bottom)
    return out
